  "worldData": {
    "location": "Capital of Lugunica",
    "time": "Afternoon",
    "turn": 1
  },
  "characters": [
    {
      "name": "Laym",
      "stats": {
        "title": "Living Dissonance",
        "role": "Karsten Knight",
        "hp": { "current": "Stabilized", "max": "Stabilized" },
        "resources": { "name": "Mana Pool", "current": "S-Rank", "max": "S-Rank" },
        "combat": {
          "target": "Petelgeuse",
          "stance": "Defensive",
          "buffs": [
            { "name": "Wind Blessing", "origin": "Crusch", "type": "pos" }
          ]
        },
        "abilities": [
          "Fire Manipulation",
